import { test } from "node:test";
import assert from "node:assert/strict";
import { JobRepo } from "../src/hiring/jobRepo.ts";
import { JobService, NotFoundError } from "../src/hiring/jobService.ts";
import { applyToJob, inbox, type Application, type ApplicationStore } from "../src/hiring/applications.ts";

const acme = { tenantId: "acme" };
const globex = { tenantId: "globex" };
const initech = { tenantId: "initech" };

function setup() {
    let clock = 1_000_000;
    const repo = new JobRepo();
    const jobs = new JobService(repo, () => clock);
    const rows: Application[] = [];
    const store: ApplicationStore = { add: async (a) => void rows.push(a), forTenant: async (t) => rows.filter((a) => a.tenantId === t) };
    let n = 0;
    const newId = () => `app-${++n}`;
    return { jobs, store, rows, newId, advance: (ms: number) => (clock += ms) };
}

const backend = { id: "j1", slug: "backend-engineer", title: "Backend Engineer", location: "Remote", status: "open" as const };

test("a careers page shows its company's open job", async () => {
    const { jobs } = setup();
    await jobs.upsert(acme, backend);
    const job = await jobs.getOpenBySlug(acme, "backend-engineer");
    assert.deepEqual([job.tenantId, job.title], ["acme", "Backend Engineer"]);
    await jobs.upsert(acme, { ...backend, id: "j2", slug: "intern", status: "draft" });
    await assert.rejects(jobs.getOpenBySlug(acme, "intern"), NotFoundError);
});

test("two companies using the same slug each see their own posting", async () => {
    const { jobs } = setup();
    await jobs.upsert(acme, { ...backend, title: "Backend Engineer (Payments)" });
    await jobs.upsert(globex, { ...backend, id: "g7", title: "Senior Backend Engineer", location: "Berlin" });
    const a = await jobs.getOpenBySlug(acme, "backend-engineer");
    const g = await jobs.getOpenBySlug(globex, "backend-engineer");
    console.log("globex careers page got:", g);
    assert.deepEqual([a.tenantId, a.title], ["acme", "Backend Engineer (Payments)"]);
    assert.deepEqual([g.tenantId, g.title, g.location], ["globex", "Senior Backend Engineer", "Berlin"]);
});

test("a company without a job at that slug gets a 404, even right after another company's page was viewed", async () => {
    const { jobs } = setup();
    await jobs.upsert(acme, backend);
    await jobs.getOpenBySlug(acme, "backend-engineer");
    await assert.rejects(jobs.getOpenBySlug(initech, "backend-engineer"), NotFoundError);
});

test("an application lands in the inbox of the company whose careers page it came from", async () => {
    const { jobs, store, newId } = setup();
    await jobs.upsert(acme, backend);
    await jobs.upsert(globex, { ...backend, id: "g7" });
    await jobs.getOpenBySlug(acme, "backend-engineer");
    const app = await applyToJob(jobs, store, globex, "backend-engineer", { email: "sam@example.com", resumeText: "10 years of Go" }, newId);
    assert.deepEqual([app.tenantId, app.jobId], ["globex", "g7"]);
    assert.deepEqual((await inbox(store, acme)).map((a) => a.candidateEmail), []);
    assert.deepEqual((await inbox(store, globex)).map((a) => a.candidateEmail), ["sam@example.com"]);
});

test("editing a job shows on the careers page right away, and closing it takes it down", async () => {
    const { jobs } = setup();
    await jobs.upsert(acme, backend);
    await jobs.getOpenBySlug(acme, "backend-engineer");
    await jobs.upsert(acme, { ...backend, location: "London" });
    assert.equal((await jobs.getOpenBySlug(acme, "backend-engineer")).location, "London");
    await jobs.upsert(acme, { ...backend, status: "closed" });
    await assert.rejects(jobs.getOpenBySlug(acme, "backend-engineer"), NotFoundError);
});

test("renaming a slug retires the old URL", async () => {
    const { jobs, advance } = setup();
    await jobs.upsert(acme, backend);
    await jobs.getOpenBySlug(acme, "backend-engineer");
    await jobs.upsert(acme, { ...backend, slug: "platform-engineer" });
    await assert.rejects(jobs.getOpenBySlug(acme, "backend-engineer"), NotFoundError);
    advance(61_000);
    assert.equal((await jobs.getOpenBySlug(acme, "platform-engineer")).id, "j1");
});

test("job lists and recruiter inboxes only contain the caller's own company", async () => {
    const { jobs, store, newId } = setup();
    await jobs.upsert(acme, backend);
    await jobs.upsert(globex, { ...backend, id: "g1", slug: "sre" });
    await applyToJob(jobs, store, acme, "backend-engineer", { email: "kim@example.com", resumeText: "" }, newId);
    assert.deepEqual((await jobs.listOpen(globex)).map((j) => j.id), ["g1"]);
    assert.deepEqual((await inbox(store, globex)).length, 0);
    await assert.rejects(applyToJob(jobs, store, acme, "sre", { email: "kim@example.com", resumeText: "" }, newId), NotFoundError);
});
